package build

import (
	"strings"
	"testing"
)

// TestIsGeneratedNginxConfMarker pins the exported marker test the deploy
// staging relies on: the build's own marker within the first 128 bytes, nothing
// else, and the same answer the sites sweep gives.
func TestIsGeneratedNginxConfMarker(t *testing.T) {
	for name, tc := range map[string]struct {
		head string
		want bool
	}{
		"template header":      {"# Generated by nself build - DO NOT EDIT MANUALLY\nserver {}\n", true},
		"plugin snippet stamp": {nginxGeneratedMarker + "\nlocation / {}\n", true},
		"marker on line 2":     {"# Service: x\n" + nginxGeneratedMarker + "\n", true},
		"empty":                {"", false},
		"hand written":         {"# my conf\nserver {}\n", false},
		"ssl add stamp":        {"# Generated by nself ssl add\nserver {}\n", false},
		"blue/green upstream":  {"upstream nself_api {\n    server 127.0.0.1:8080 weight=100;   # blue\n}\n", false},
		"marker past 128":      {strings.Repeat("#", NginxGeneratedHeadBytes) + nginxGeneratedMarker, false},
		"marker ends at 128":   {strings.Repeat("#", NginxGeneratedHeadBytes-len(nginxGeneratedMarker)) + nginxGeneratedMarker, true},
	} {
		if got := IsGeneratedNginxConf([]byte(tc.head)); got != tc.want {
			t.Errorf("%s: IsGeneratedNginxConf = %v, want %v", name, got, tc.want)
		}
	}
}
